"""Transparent default rubrics, not validated literary norms or ideology tests."""
from .evaluation_models import Rubric,Criterion,Anchors
DETAILS={
 'style':('语言与文风','结合选定作品目标，评估句式节奏、叙事距离、词语精确度、对白差异与表达效果；风格变化不自动是错误。','反复出现妨碍理解或与目标相悖的表达，缺少有效控制的具体证据。','表达大体清晰，局部语言有效，节奏与叙事距离仍有可定位的松动。','语言选择、节奏、距离与声音协同表达，效果持续且有充分具体证据；高分不要求华丽。'),
 'character':('人物塑造','评估人物欲望、行动、矛盾、代价、表达差异与在当前范围内的变化；不要求所有人物完成成长。','所选文本多处以功能代替人物，关键行为缺少可理解的条件。','人物目标与行动大体成立，有可辨细节，部分转折或差异尚显薄弱。','人物选择、处境、关系与后果相互支撑，复杂性有正文证据，而非依赖设定说明。'),
 'structure':('叙事结构','仅评当前范围内的组织、场景转折、信息顺序与节奏，不凭选区推断全书结构。','当前范围的组织反复遮断必要因果或削弱预期效果，须列具体位置。','局部或章节组织可读，主要转折成立，部分安排的效果不稳定。','适合本作意图的组织、节奏和信息顺序相互支持；自由结构同样可以取得高分。'),
 'thought':('思想与主题','关注问题深度、价值张力、人物经历与代价、表达及有意义的歧义；不判断政治立场正确性。','本次可见的思想表达反复简化对立观点或脱离人物行动，须有证据。','可辨的问题与冲突通过部分人物经历呈现，复杂理由和代价尚未充分展开。','多种有分量的立场通过处境、选择和后果相互挑战，表达有深度与开放性；不要求给出答案。'),
 'clue':('伏笔与悬念','评估当前范围内的问题、线索组织、披露与阅读动力；未到回收处或缺少中间章节不机械扣分。','所选范围内的信息组织反复破坏其声明的效果，且无合理误导解释。','线索与疑问可识别，部分披露有效，有些安排仍缺乏支撑或辨识度。','线索、悬念、误导和披露在当前范围产生可追溯效果；开放结尾无需全部回收。'),
 'logic':('叙事逻辑','评估可见的动机、知识、事件前提与世界规则的内部支撑；谎言、倒叙与留白不是当然错误。','有充分证据表明关键前提或行为反复缺乏支撑；不将 AI 猜测当作确定矛盾。','多数可见因果与人物行动可理解，仍有影响理解的前提缺口。','因果、知识与行动在已见范围内有可靠支撑，例外和不确定性得到恰当处理。'),
 'emotion':('情感表现','评估情感如何由细节、关系、节奏、行动和语境形成；克制、冷静和不愉悦不等于低质量。','表达反复依赖缺乏铺垫的标签或强迫反应，与具体处境脱节。','部分情感通过细节与选择成立，个别转折、层次或余味尚不充分。','情感效果由处境、细节、关系和行动自然形成且具有层次；强烈程度不是评分标准。'),
 'innovation':('文学创新性','评估形式、视角、语言或题材处理的独特性与实际表达作用；偏离传统本身不加分，判断受模型阅读经验限制。','能指出具体的套路化选择如何削弱本次表达；不能只因采用成熟形式就扣分。','在既有形式中有适合文本的具体选择，独特性和表达作用尚有限或证据不足。','独特处理与作品意图相互成就，能用原文说明效果；不宣称此前从未有人写过。')}
def defaults():
 result=[]
 for kind,name in [('literary','文学创作'),('genre','类型小说')]:
  weights={k:1 for k in DETAILS}
  if kind=='literary':weights.update(style=1.5,thought=1.5,character=1.5)
  else:weights.update(character=1.5,structure=1.5,clue=1.5,logic=1.5)
  r=Rubric(name=name,version='2.12.1-1',positioning='作者可修改的辅助评价配置，不是公认文学标准。',dimensions=[Criterion(id=k,weight=weights[k],focus=v[1],anchors=Anchors(low='0–49：'+v[2],middle='50–79：'+v[3],high='80–100：'+v[4]+' 90 分以上需要持续、具体且充分的支撑，不能默认给高分。')) for k,v in DETAILS.items()]);result.append({'id':kind,'rubric':r.model_dump()})
 return result
